export function validateAccessToken(value: string): boolean {
  const segments = value.split('.');
  return segments.length === 3 && segments.every(Boolean);
}

import * as path from 'path';

export function assertMutationTarget(candidate: string, root: string): void {
  const relative = path.relative(root, candidate);
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    throw new Error('Target is outside the permitted root.');
  }
}

export const retryDelays = [250, 750, 1500] as const;

export function isTransientProviderFailure(status: number): boolean {
  return [408, 429, 502, 503, 504].includes(status);
}

export function loadSession(id: string): StoredSession | undefined {
  return sessions.get(id);
}

export function saveSession(session: StoredSession): void {
  sessions.set(session.id, session);
}

export function routeIncomingMessage(message: WebviewMessage): void {
  if (message.command === 'submitQuestion') {
    requestController.submitQuestion(message.text);
  }
}

export function postToWebview(event: ChatEvent): void {
  webview.postMessage(event);
}

export async function submitQuestion(question: string): Promise<void> {
  eventSink.emit({ type: 'request-started' });
  const answer = await backendGateway.streamAnswer(question);
  eventSink.emit({ type: 'answer-completed', answer });
}

export async function streamAnswer(question: string): Promise<string> {
  const response = await authenticatedRequest('/ask/stream', { question });
  return consumeServerSentEvents(response);
}

export function collectFailedCommandOutput(events: TerminalExecution[]): string {
  return events.filter((event) => event.exitCode !== 0)
    .map((event) => sanitizeAnsi(event.output))
    .join('\n');
}

export async function authorizeMutation(operation: MutationOperation): Promise<boolean> {
  const policy = await loadPolicy(operation.kind);
  const decision = policy === 'allow' ? true : await presentApproval(operation);
  return decision;
}

export function searchProducts(query: string): Product[] {
  return catalog.filter((product) => product.name.includes(query));
}

export async function rejectSymbolicPath(candidate: Uri): Promise<void> {
  const attributes = await lstat(candidate);
  if (attributes.type === FileType.SymbolicLink) {
    throw new UnsafePathError(candidate.fsPath);
  }
}
